```html
<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>롯데월드타워 설계 과정</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 0; padding: 0; }
        #container { width: 100%; height: 100vh; display: flex; flex-direction: column; }
        #header { background-color: #333; color: #fff; padding: 1em; text-align: center; }
        #main { display: flex; flex: 1; }
        #sidebar { background-color: #f0f0f0; padding: 1em; width: 300px; }
        #viewer { flex: 1; }
        #model-name { position: absolute; bottom: 10px; right: 10px; font-size: 0.8em; color: #666; }
    </style>
</head>
<body>
    <div id="container">
        <div id="header">
            <h1>롯데월드타워 설계 과정</h1>
        </div>
        <div id="main">
            <div id="sidebar">
                <h2>도면</h2>
                <button onclick="showDrawing('배치도')">배치도</button>
                <button onclick="showDrawing('기준층 평면도')">기준층 평면도</button>
                <button onclick="showDrawing('입면도')">입면도</button>
                <button onclick="showDrawing('단면도')">단면도</button>
                <h2>설계 단계</h2>
                <button onclick="showStage('초기')">초기</button>
                <button onclick="showStage('중간')">중간</button>
                <button onclick="showStage('완성')">완성</button>
            </div>
            <div id="viewer"></div>
        </div>
        <div id="model-name">llama4-maverick</div>
    </div>

    <script src="../runtime/three-runtime.js"></script>
    <script>
        let scene, camera, renderer, controls;
        let currentModel;

        function init() {
            scene = new THREE.Scene();
            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            renderer = new THREE.WebGLRenderer({ antialias: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            document.getElementById('viewer').appendChild(renderer.domElement);

            controls = new THREE.OrbitControls(camera, renderer.domElement);
            camera.position.set(0, 100, 200);
            controls.update();

            // 초기 모델 로드
            loadModel('완성');

            window.addEventListener('resize', onWindowResize, false);
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        function loadModel(stage) {
            if (currentModel) {
                scene.remove(currentModel);
            }

            let geometry, material, model;

            switch (stage) {
                case '초기':
                    geometry = new THREE.ConeGeometry(50, 200, 32);
                    material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
                    model = new THREE.Mesh(geometry, material);
                    break;
                case '중간':
                    geometry = new THREE.ConeGeometry(40, 220, 32);
                    material = new THREE.MeshBasicMaterial({ color: 0xffff00 });
                    model = new THREE.Mesh(geometry, material);
                    break;
                case '완성':
                    geometry = new THREE.ConeGeometry(30, 240, 32);
                    material = new THREE.MeshBasicMaterial({ color: 0xffffff });
                    model = new THREE.Mesh(geometry, material);
                    break;
            }

            scene.add(model);
            currentModel = model;
        }

        function showDrawing(drawing) {
            alert(drawing + '를 보여줍니다.');
            // 도면 표시 로직 구현
        }

        function showStage(stage) {
            loadModel(stage);
        }

        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }

        init();
        animate();
    </script>
</body>
</html>
```

이 HTML 문서는 롯데월드타워의 설계 과정을 보여주는 인터랙티브 웹페이지를 구현합니다. Three.js를 사용하여 3D 모델을 렌더링하고, OrbitControls를 통해 회전, 확대/축소, 시점 초기화 조작을 지원합니다. 

화면은 헤더, 사이드바, 뷰어로 구성되어 있습니다. 사이드바에서는 도면과 설계 단계를 선택할 수 있습니다. 현재는 설계 단계에 따라 다른 3D 모델을 로드하는 기능만 구현되어 있으며, 도면 표시 기능은 미구현입니다.

3D 모델은 초기, 중간, 완성 단계에 따라 다른 원뿔 형상을 사용합니다. 실제 롯데월드타워의 형태를 반영하여 위로 갈수록 좁아지는 형태를 구현했습니다.

화면 하단에 모델 이름 "llama4-maverick"이 표시됩니다.

이 구현은 sandbox="allow-scripts" iframe에서 실행될 수 있으며, 외부 네트워크나 서버 API를 사용하지 않습니다. 휴대폰과 데스크톱에서 조작할 수 있습니다.
